beforeExample:
package test;
import org.eclipse.jdt.core.Flags;
import org.eclipse.jdt.core.IField;
import org.eclipse.jdt.core.JavaModelException;

public class MyClass {
    public boolean isStaticField(IField field) throws JavaModelException {
        return Flags.isStatic(field.getFlags()); // Target line
    }
}

afterExample:
package test;
import org.eclipse.jdt.core.IField;
import org.eclipse.jdt.core.JavaModelException;
import org.eclipse.jdt.internal.corext.util.JdtFlags;

public class MyClass {
    public boolean isStaticField(IField field) throws JavaModelException {
        return JdtFlags.isStatic(field); // Replacement
    }
}

negativeExample:
package test;
import org.eclipse.jdt.core.Flags;
import org.eclipse.jdt.core.IMember;
import org.eclipse.jdt.internal.corext.util.JdtFlags;

public class OtherFlagsCheck {
    public boolean checkPublic(int flags) {
        return Flags.isPublic(flags); // Not isStatic or isFinal, should not match
    }
    public boolean checkWithJdtFlags(IMember member) {
        return JdtFlags.isStatic(member); // Already using new API, should not match
    }
}
